/*
 * Who Drew These Lines? One map that changes with the chapter being read.
 * Data: window.GEO (data/geo.js, generated by build/build.py) and window.CONTENT (js/content.js).
 */
(() => {
  const G = window.GEO, C = window.CONTENT;
  // Translation: the English text is the key (js/lang-hi.js fills window.LANG_DICT); {name} fills values
  const DICT = window.LANG_DICT || {};
  const T = (s, vars = {}) => (DICT[s] ?? s).replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m));
  const TL = s => (s || "").split(/,\s*/).filter(Boolean).map(l => T(l)).join(T(", "));
  const $ = s => document.querySelector(s);
  const NS = "http://www.w3.org/2000/svg";
  const el = (tag, attrs = {}, parent) => {
    const n = document.createElementNS(NS, tag);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    if (parent) parent.append(n);
    return n;
  };
  const html = (tag, attrs = {}, text) => {
    const n = document.createElement(tag);
    for (const k in attrs) n.setAttribute(k, attrs[k]);
    if (text != null) n.textContent = text;
    return n;
  };
  const esc = s => String(s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);

  // ---------------------------------------------------------------- Projection (same as build/geo.py)
  const P = G.proj, D2R = Math.PI / 180, L0 = P.lon0 * D2R, F0 = P.lat0 * D2R;
  function proj(lon, lat) {
    const l = lon * D2R, f = lat * D2R;
    const k = Math.sqrt(2 / (1 + Math.sin(F0) * Math.sin(f) + Math.cos(F0) * Math.cos(f) * Math.cos(l - L0)));
    const x = P.k * k * Math.cos(f) * Math.sin(l - L0);
    const y = P.k * k * (Math.cos(F0) * Math.sin(f) - Math.sin(F0) * Math.cos(f) * Math.cos(l - L0));
    return [x - P.ox, -y - P.oy];
  }

  // ---------------------------------------------------------------- Colours
  const CAT = {
    maurya: "#d9783f", core: "#a8402c", conquered: "#eeb05a", free: "#e6dcc5", other: "#c9bfae",
    mughal: "#3f8f6b", ally: "#a3cfae", maratha: "#e3a12f", euro: "#4a6fb3", company: "#c23b32", afghan: "#9a7bb0",
    brit: "#d4574a", prince: "#f2c94c", colony: "#e7a39a",
    india: "#f2b25c", foreign: "#d9d1bf", area: "#d8cfe8", PK: "#7fb58a"
  };
  const CAT_LABEL = {
    maurya: "Maurya Empire", core: "Magadha, the heart", conquered: "Kalinga, conquered", free: "Peoples ruling themselves",
    other: "Other states", mughal: "Mughal Empire", ally: "Allies and tribute-payers", maratha: "Marathas",
    euro: "European ports", company: "East India Company", afghan: "Durrani Empire", kingdom: "Other kingdoms",
    brit: "British India", prince: "Princely states", colony: "Other British colonies"
  };
  const KINGDOM = ["#c9a26b", "#b98a7a", "#dcc08f", "#a99a6a", "#c48a5a", "#b3a089", "#d4a983", "#9f8d74", "#cdb48c"];
  const TODAY = ["#f6c86b", "#9ccf8f", "#f1a07a", "#8fc0e0", "#e7a6c8", "#c6b2e3", "#f3d98d", "#9fd6c8", "#e9b48a", "#b8d38b"];

  function bbox(d) {
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    for (const m of d.matchAll(/(-?[\d.]+),(-?[\d.]+)/g)) {
      const x = +m[1], y = +m[2];
      if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y;
    }
    return [x0, y0, x1, y1];
  }
  const touch = (a, b, m = 4) => a[0] - m < b[2] && b[0] - m < a[2] && a[1] - m < b[3] && b[1] - m < a[3];
  function greedy(ds, palette) {
    const boxes = ds.map(bbox), out = [];
    ds.forEach((d, i) => {
      const used = new Set();
      for (let j = 0; j < i; j++) if (touch(boxes[i], boxes[j])) used.add(out[j]);
      out.push(palette.find(c => !used.has(c)) || palette[i % palette.length]);
    });
    return out;
  }

  // ---------------------------------------------------------------- Map skeleton
  const svg = $("#map");
  svg.setAttribute("viewBox", G.viewBox.join(" "));
  // the part of the frame that must always be seen: South Asia and Afghanistan
  const CONTENT_BOX = (() => {
    const a = bbox(G.land), b = bbox(G.eras["-250"].units.map(u => u.d).join(""));
    return [Math.min(a[0], b[0]) - 8, Math.min(a[1], b[1]) - 8, Math.max(a[2], b[2]) + 8, Math.max(a[3], b[3]) + 8];
  })();
  function fitMap() {
    const bw = svg.clientWidth, bh = svg.clientHeight;
    if (!bw || !bh) return;
    const top = 46, bottom = (legend.offsetHeight || 0) + 14;
    const [x0, y0, x1, y1] = CONTENT_BOX, W = x1 - x0, H = y1 - y0;
    const avail = Math.max(60, bh - top - bottom);
    const s = Math.min(bw / W, avail / H);
    const vw = bw / s, vh = bh / s;
    const vx = x0 - (vw - W) / 2, vy = y0 - top / s - (avail / s - H) / 2;
    svg.setAttribute("viewBox", [vx, vy, vw, vh].map(v => v.toFixed(1)).join(" "));
    // keep names inside the visible map
    for (const t of L.labels.querySelectorAll("text")) {
      const x = +(t.dataset.x ??= t.getAttribute("x")), w = t.getBBox().width;
      const lo = vx + w / 2 + 6, hi = vx + vw - w / 2 - 6;
      if (lo < hi) t.setAttribute("x", Math.min(hi, Math.max(lo, x)).toFixed(1));
    }
    for (const g of L.points.querySelectorAll(".pt")) {
      const c = g.querySelector("circle"), t = g.querySelector("text"), cx = +c.getAttribute("cx"), r = +c.getAttribute("r");
      const right = cx + r + 3 + t.getBBox().width > vx + vw - 4;
      t.setAttribute("x", right ? cx - r - 3 : cx + r + 3);
      t.setAttribute("text-anchor", right ? "end" : "start");
    }
  }
  const defs = el("defs", {}, svg);
  function hatch(id, color, bg = "none", w = 3, gap = 7) {
    const p = el("pattern", { id, patternUnits: "userSpaceOnUse", width: gap, height: gap, patternTransform: "rotate(45)" }, defs);
    if (bg !== "none") el("rect", { width: gap, height: gap, fill: bg }, p);
    el("rect", { width: w, height: gap, fill: color }, p);
    return `url(#${id})`;
  }
  hatch("hatchPrince", "#c9a227", "none", 2.2, 6);
  const UT_FILL = hatch("hatchUT", "#b9a6dc", "#f4effa", 3, 7);
  const stripes = {};
  function stripe(a, b) {
    const id = `st-${a.slice(1)}-${b.slice(1)}`;
    if (!stripes[id]) stripes[id] = hatch(id, b, a, 5, 10);
    return stripes[id];
  }

  el("rect", { x: -50, y: -50, width: G.viewBox[2] + 100, height: G.viewBox[3] + 100, class: "sea" }, svg);
  el("path", { d: G.context, class: "context" }, svg);
  const names = el("g", { "aria-hidden": "true" }, svg);
  for (const [n, [x, y]] of G.contextNames) el("text", { x, y, class: "context-name" }, names).textContent = T(n);
  for (const [n, [x, y]] of G.seaNames) el("text", { x, y, class: "sea-name" }, names).textContent = T(n);

  const layer = name => el("g", { class: `layer layer-${name}` }, svg);
  const L = { era: layer("era"), pieces: layer("pieces"), edges: layer("edges"), overlay: layer("overlay"), coast: layer("coast"),
    hl: layer("hl"), route: layer("route"), labels: layer("labels"), points: layer("points") };
  L.edges.classList.add("edges");
  L.pieces.classList.add("pieces");
  el("path", { d: G.land, class: "coast" }, L.coast);

  // ---------------------------------------------------------------- Eras (250 BCE, 1707, 1760, 1909)
  const eraPaths = {};
  function buildEra(key) {
    const g = el("g", { "data-era": key }, L.era);
    const units = G.eras[key].units;
    const kfill = greedy(units.map(u => u.d || `M${u.l[0]},${u.l[1]}`), KINGDOM);
    eraPaths[key] = units.map((u, i) => {
      const fill = u.c === "kingdom" ? kfill[i] : CAT[u.c] || "#ccc";
      const tip = u.i ? `${T(u.n)}: ${T(u.i)}` : T(u.n);
      let p = null, dot = null;
      if (u.d) p = el("path", { d: u.d, fill, class: "unit", "data-tip": tip, "data-id": u.id }, g);
      if (u.dot) dot = el("circle", { cx: u.l[0], cy: u.l[1], r: 5, fill, class: "unit dotunit", "data-tip": tip, "data-id": u.id }, g);
      return { u, p, dot, fill };
    });
    return g;
  }
  const eraGroups = {};
  function showEra(key) {
    for (const k in eraGroups) eraGroups[k].style.display = "none";
    if (!key) return;
    if (!eraGroups[key]) eraGroups[key] = buildEra(key);
    eraGroups[key].style.display = "";
    eraPaths[key].forEach(r => [r.p, r.dot].forEach(n => n && n.classList.remove("faded", "picked")));
  }
  function fadeEra(key, keep) {
    eraPaths[key].forEach(r => [r.p, r.dot].forEach(n => n && n.classList.toggle("faded", !keep(r.u))));
  }

  // ---------------------------------------------------------------- Pieces (1947, 1956, the years after, today)
  const pieceKeys = Object.keys(G.pieces);
  const piecePaths = {}, pieceDots = {};
  for (const k of pieceKeys) {
    const pc = G.pieces[k];
    if (pc.d) piecePaths[k] = el("path", { d: pc.d, class: "unit", "data-piece": k }, L.pieces);
    if (pc.dot) pieceDots[k] = el("circle", { cx: pc.l[0], cy: pc.l[1], r: 4.5, class: "unit dotunit", "data-piece": k }, L.pieces);
  }
  const edgePaths = G.edges.map(([a, b, d]) => ({ a, b, p: el("path", { d }, L.edges) }));
  function unitAt(piece, y) {
    let u = null;
    for (const [from, unit] of G.timeline[piece]) if (from <= y) u = unit;
    return u;
  }
  const langsOf = key => (G.units[key].lang || "").split(/,\s*/).filter(Boolean);
  function langFill(key) {
    const c = G.units[key].c;
    if (c === "foreign" || c === "euro") return CAT[c];
    const ls = langsOf(key).map(l => C.LANG_COLORS[l]).filter(Boolean);
    if (!ls.length) return C.LANG_COLORS.other;
    return ls.length > 1 ? stripe(ls[0], ls[1]) : ls[0];
  }
  // stable colours for today's states
  const todayFill = (() => {
    const units = [...new Set(pieceKeys.map(k => unitAt(k, 2026)))];
    const ds = units.map(u => pieceKeys.filter(k => unitAt(k, 2026) === u).map(k => G.pieces[k].d || "").join(""));
    const fills = greedy(ds, TODAY);
    return Object.fromEntries(units.map((u, i) => [u, fills[i]]));
  })();
  function fillFor(mode, unit) {
    const c = G.units[unit].c;
    if (mode === "lang") return langFill(unit);
    if (mode === "1947") return unit.startsWith("PK_") ? CAT.PK : CAT[c] || CAT.foreign;
    if (c === "ut") return UT_FILL;
    if (c === "foreign") return CAT.foreign;
    return todayFill[unit];
  }
  function unitTip(unit, mode) {
    const u = G.units[unit];
    if (mode === "1947" || !u.lang) return T(u.n);
    return `${T(u.n)} · ${TL(u.lang)}`;
  }
  function paintPieces(year, mode) {
    for (const k of pieceKeys) {
      const unit = unitAt(k, year);
      for (const n of [piecePaths[k], pieceDots[k]]) {
        if (!n) continue;
        n.setAttribute("fill", fillFor(mode, unit));
        n.dataset.tip = unitTip(unit, mode);
        n.classList.toggle("ut", G.units[unit].c === "ut");
      }
    }
    for (const e of edgePaths) e.p.style.display = unitAt(e.a, year) === unitAt(e.b, year) ? "none" : "";
    labelPieces(year, mode);
  }
  function labelPieces(year, mode) {
    L.labels.replaceChildren();
    const byUnit = {};
    for (const k of pieceKeys) {
      const u = unitAt(k, year), pc = G.pieces[k];
      (byUnit[u] ||= []).push(pc);
    }
    const minA = innerWidth < 900 ? 9000 : 5000;
    if (year >= 1970) {
      const pk = G.pieces.PK_PUNJAB, bd = G.pieces.PK_BALOCH;
      label((pk.l[0] + bd.l[0]) / 2, (pk.l[1] + bd.l[1]) / 2, T("PAKISTAN"), "small");
    }
    for (const u in byUnit) {
      if (year >= 1970 && u.startsWith("PK_")) continue;
      const area = byUnit[u].reduce((s, p) => s + p.a, 0);
      if (area < minA) continue;
      const big = byUnit[u].reduce((a, b) => (b.a > a.a ? b : a));
      let name = T(G.units[u].n).replace(/ \(.*\)$/, "");
      if (mode === "1947" && u === "IN") name = T("INDIA");
      label(big.l[0], big.l[1], name, area > 60000 ? "big" : "small");
    }
  }
  function label(x, y, text, cls = "") {
    const t = el("text", { x, y, class: `lbl ${cls}` }, L.labels);
    t.textContent = text;
    return t;
  }
  function eraLabels(key, min = 4000, only = null) {
    L.labels.replaceChildren();
    const minA = innerWidth < 900 ? min * 1.8 : min;
    for (const u of G.eras[key].units) {
      if (only ? !only.includes(u.id) : u.a < minA) continue;
      label(u.l[0], u.l[1], T(u.n).replace(/ \(.*\)$/, "").split(/[,،]/)[0], u.a > 60000 ? "big" : "small");
    }
  }

  // princely states overlay for 1947
  for (const u of G.eras["1909"].units) if (u.c === "prince" && u.id !== "shan" && u.d) el("path", { d: u.d, class: "prince-overlay" }, L.overlay);

  // ---------------------------------------------------------------- Points
  const pointNodes = [];
  function addPoint(name, [x, y], color, tip, onClick, r = 6, key = name) {
    const g = el("g", { class: r >= 7 ? "pt cap" : "pt", "data-tip": tip, "data-key": key }, L.points);
    el("circle", { cx: x, cy: y, r, fill: color, "data-tip": tip }, g);
    const t = el("text", { x: x + r + 3, y: y + 5 }, g);
    t.textContent = name;
    if (onClick) g.addEventListener("click", e => { e.stopPropagation(); onClick(); });
    pointNodes.push(g);
    return g;
  }
  const POINT_COLORS = { capital: "#2b2118", rock: "#7a4a2a", minor: "#a8774f", pillar: "#4a6fb3", city: "#2b2118", fort: "#e3a12f",
    battle: "#c23b32", british: "#c23b32", french: "#3d6cb3", dutch: "#e07b22", danish: "#8a5fa8" };
  function showPoints(key, filter = () => true) {
    L.points.replaceChildren();
    for (const p of G.eras[key].points) if (filter(p)) addPoint(T(p.n), p.p, POINT_COLORS[p.k] || "#2b2118", p.t ? `${T(p.n)}: ${T(p.t)}` : T(p.n),
      key === "-250" ? () => pickEdict(p) : null, p.k === "capital" ? 7 : 5.5, p.n);
  }

  // ---------------------------------------------------------------- Legend, notes
  const legend = $("#mapLegend");
  const sw = (c, t) => `<span><i style="background:${c}"></i>${esc(t)}</span>`;
  function setLegend(items) { legend.innerHTML = items.map(([c, t]) => sw(c, t)).join(""); }
  const catLegend = cats => setLegend(cats.map(c => [c === "kingdom" ? KINGDOM[0] : CAT[c], T(CAT_LABEL[c])]));
  function showHint(text) { const h = $("#mapHint"); h.textContent = text; h.hidden = false; }
  const note = t => { $("#mapNote").textContent = t || ""; };

  // ---------------------------------------------------------------- Chapter states
  let state = null, year = 1956, timer = null;
  const STATES = {
    maurya() {
      $("#mapYear").textContent = T("250 BCE");
      showEra("-250"); eraLabels("-250", 9000, ["maurya", "kalinga", "magadha", "chola", "pandya", "chera", "tamraparni"]);
      showPoints("-250");
      catLegend(["maurya", "core", "conquered", "kingdom", "free"]);
      note(T("Simplified: historians debate how far Ashoka really ruled."));
      if (pickedScript) pickScript(pickedScript);
    },
    mughal() {
      $("#mapYear").textContent = "1707";
      showEra("1707"); eraLabels("1707", 9000);
      showPoints("1707");
      catLegend(["mughal", "ally", "maratha", "kingdom", "free", "euro"]);
      note(T("Simplified map of 1707."));
    },
    "1760"() {
      $("#mapYear").textContent = "1760";
      showEra("1760"); eraLabels("1760", 9000);
      showPoints("1760", p => ["capital", "battle"].includes(p.k));
      catLegend(["maratha", "afghan", "kingdom", "company", "euro", "free"]);
      note(T("After C. Colbeck, India in the time of Clive (1884), simplified."));
    },
    company() {
      $("#mapYear").textContent = "1757–1858";
      showEra("1760"); fadeEra("1760", u => u.c === "company" || u.c === "euro");
      eraLabels("1760", 0, ["company"]);
      showPoints("1760", p => ["british", "french", "dutch", "danish", "battle"].includes(p.k));
      setLegend([[POINT_COLORS.british, T("British")], [POINT_COLORS.french, T("French")], [POINT_COLORS.dutch, T("Dutch")], [POINT_COLORS.danish, T("Danish")], [POINT_COLORS.battle, T("Battle")]]);
      note(T("Trading posts in 1760."));
    },
    "1909"() {
      $("#mapYear").textContent = "1909";
      showEra("1909"); eraLabels("1909", 9000);
      showPoints("1909", p => p.k === "capital");
      catLegend(["brit", "prince", "colony", "euro"]);
      note(T("After the Imperial Gazetteer of India atlas (1909)."));
      if (lastGuess) highlightUnit("1909", lastGuess);
    },
    bengal() {
      $("#mapYear").textContent = "1905–1911";
      showEra("1909"); fadeEra("1909", u => ["bengal", "ebengal"].includes(u.id));
      eraLabels("1909", 0, ["bengal", "ebengal"]);
      highlightUnit("1909", "ebengal");
      L.points.replaceChildren();
      addPoint(T("Calcutta"), proj(88.36, 22.57), "#2b2118", T("Calcutta"));
      addPoint(T("Dacca"), proj(90.41, 23.71), "#2b2118", T("Dacca (Dhaka), capital of Eastern Bengal and Assam"));
      legend.innerHTML = sw(CAT.brit, T("Bengal and Eastern Bengal and Assam, 1905–1911"));
      note("");
    },
    freedom() {
      $("#mapYear").textContent = "1857–1947";
      showEra("1909"); fadeEra("1909", () => false);
      L.labels.replaceChildren();
      L.points.replaceChildren();
      C.FREEDOM.forEach((f, i) => addPoint(f[0], proj(f[1], f[2]), "#c23b32", `${f[0]} (${f[3]}): ${f[4]}`, () => pickFreedom(i), 6.5));
      el("path", { d: "M" + C.SALT_MARCH.map(([a, b]) => proj(a, b).map(v => v.toFixed(1)).join(",")).join("L"), class: "route" }, L.route);
      setLegend([["#c23b32", T("Places of the freedom struggle")]]);
      note("");
      if (pickedFreedom != null) pickFreedom(pickedFreedom);
    },
    "1947"() {
      $("#mapYear").textContent = "1947";
      L.pieces.style.display = L.edges.style.display = "";
      paintPieces(1947, "1947");
      L.overlay.style.display = "";
      L.points.replaceChildren();
      legend.innerHTML = sw(CAT.india, T("India")) + sw(CAT.PK, T("Pakistan")) + sw(CAT.euro, T("Portuguese and French")) +
        `<span><i style="background:repeating-linear-gradient(45deg,#c9a227 0 2px,transparent 2px 6px)"></i>${esc(T("Princely states (1909)"))}</span>`;
      note(T("Borders of 1947. The outline of India follows the official map of India."));
    },
    "1956"() {
      $("#mapYear").textContent = "1956";
      L.pieces.style.display = L.edges.style.display = "";
      paintPieces(1956, "lang");
      L.points.replaceChildren();
      langLegend(1956);
      note(T("Colours: main language of each state."));
    },
    changes() {
      L.pieces.style.display = L.edges.style.display = "";
      L.points.replaceChildren();
      paintYear(year);
      note(T("Colours: main language of each state."));
    },
    today() {
      $("#mapYear").textContent = T("Today");
      L.pieces.style.display = L.edges.style.display = "";
      paintPieces(2026, "today");
      L.points.replaceChildren();
      legend.innerHTML = sw(TODAY[0], T("States")) + `<span><i style="background:repeating-linear-gradient(45deg,#b9a6dc 0 3px,#f4effa 3px 7px)"></i>${esc(T("Union territories"))}</span>` + sw(CAT.foreign, T("Neighbouring countries"));
      note(T("The outline of India follows the official map of India."));
    }
  };
  function langLegend(y) {
    const seen = new Map();
    for (const k of pieceKeys) {
      const u = unitAt(k, y);
      if (["state", "ut"].includes(G.units[u].c)) for (const l of langsOf(u)) if (C.LANG_COLORS[l] && !seen.has(l)) seen.set(l, C.LANG_COLORS[l]);
    }
    setLegend([...seen].slice(0, 14).map(([l, c]) => [c, T(l)]));
  }

  function highlightUnit(key, id) {
    L.hl.replaceChildren();
    const u = G.eras[key].units.find(v => v.id === id);
    if (u && u.d) el("path", { d: u.d, class: "hl" }, L.hl);
  }

  function setState(name) {
    if (name === state) return;
    state = name;
    stopYears();
    L.labels.replaceChildren(); L.hl.replaceChildren(); L.route.replaceChildren(); L.points.replaceChildren();
    L.pieces.style.display = L.edges.style.display = L.overlay.style.display = "none";
    showEra(null);
    $("#mapHint").hidden = true;
    hideTip();
    STATES[name]();
    fitMap();
  }

  // ---------------------------------------------------------------- Tooltip
  const tip = $("#tip"), box = $("#mapBox");
  function hideTip() { tip.hidden = true; }
  function showTipAt(e, text) {
    const r = box.getBoundingClientRect();
    tip.textContent = text;
    tip.hidden = false;
    const x = Math.min(e.clientX - r.left + 12, r.width - tip.offsetWidth - 6);
    tip.style.left = `${Math.max(6, x)}px`;
    tip.style.top = `${Math.max(6, e.clientY - r.top - tip.offsetHeight - 10)}px`;
  }
  const tipOf = t => t.closest && (t.closest("[data-tip]")?.dataset.tip);
  svg.addEventListener("pointermove", e => { const t = tipOf(e.target); t ? showTipAt(e, t) : hideTip(); });
  svg.addEventListener("pointerleave", hideTip);
  svg.addEventListener("click", e => {
    if (!matchMedia("(hover: none)").matches) return;
    const t = tipOf(e.target);
    t ? showTipAt(e, t) : hideTip();
  });

  // ---------------------------------------------------------------- Chapter 1: scripts of the edicts
  const scriptOf = name => C.EDICT_SCRIPT[name] || "brahmi";
  let pickedScript = null;
  function pickScript(s) {
    pickedScript = s;
    document.querySelectorAll("#scriptChips button").forEach(b => b.setAttribute("aria-pressed", b.dataset.s === s));
    const sites = G.eras["-250"].points.filter(p => p.k !== "capital" && scriptOf(p.n) === s);
    $("#edictCard").innerHTML = `<b>${esc(C.SCRIPTS[s].label)}</b>: ${esc(C.SCRIPTS[s].note)} <span class="small">(${sites.map(p => esc(T(p.n))).join(T(", "))})</span>`;
    if (state !== "maurya") return;
    pointNodes.forEach(g => {
      const p = G.eras["-250"].points.find(q => q.n === g.dataset.key);
      g.classList.toggle("dim", !p || p.k === "capital" || scriptOf(p.n) !== s);
    });
  }
  function pickEdict(p) {
    if (p.k === "capital") { $("#edictCard").innerHTML = `<b>${esc(T(p.n))}</b>: ${esc(T(p.t))}`; return; }
    const kind = T({ rock: "Major rock edict", minor: "Minor rock edict", pillar: "Pillar edict" }[p.k]);
    $("#edictCard").innerHTML = `<b>${esc(T(p.n))}</b> · ${esc(kind)} · ${esc(C.SCRIPTS[scriptOf(p.n)].label)}<br>${esc(T(p.t))}`;
  }
  for (const s in C.SCRIPTS) {
    const b = html("button", { type: "button", "data-s": s, "aria-pressed": "false" }, C.SCRIPTS[s].label);
    b.onclick = () => pickScript(s);
    $("#scriptChips").append(b);
  }

  // ---------------------------------------------------------------- Chapter 5: red or yellow?
  let lastGuess = null;
  const placeBy = n => G.places.find(p => p.n === n);
  const unit1909 = name => G.eras["1909"].units.find(u => u.n === name);
  for (const [city, answer, why] of C.GUESS) {
    const row = html("div", { class: "guess-row" });
    row.append(html("b", {}, T(city)));
    const fb = html("span", { class: "fb", "aria-live": "polite" });
    for (const [val, txt] of [["brit", T("🟥 British India")], ["prince", T("🟨 Princely state")]]) {
      const b = html("button", { type: "button" }, txt);
      b.onclick = () => {
        if (row.classList.contains("done")) return;
        row.classList.add("done");
        b.classList.add(val === answer ? "ok" : "ko");
        fb.textContent = `${val === answer ? T("✅ Yes!") : T("❌ Not quite.")} ${why}`;
        const u = unit1909(placeBy(city)?.e["1909"]);
        if (u) { lastGuess = u.id; if (state === "1909") highlightUnit("1909", u.id); }
      };
      row.append(b);
    }
    row.append(fb);
    $("#guess").append(row);
  }

  // ---------------------------------------------------------------- Chapter 7: freedom struggle
  let pickedFreedom = null;
  function pickFreedom(i) {
    pickedFreedom = i;
    const f = C.FREEDOM[i];
    document.querySelectorAll("#freedomChips button").forEach((b, j) => b.setAttribute("aria-pressed", i === j));
    $("#freedomCard").innerHTML = `<b>${esc(f[0])}, ${esc(f[3])}</b><br>${esc(f[4])}`;
    if (state === "freedom") pointNodes.forEach((g, j) => g.classList.toggle("on", i === j));
  }
  C.FREEDOM.forEach((f, i) => {
    const b = html("button", { type: "button", "aria-pressed": "false" }, `${f[0]} ${f[3]}`);
    b.onclick = () => pickFreedom(i);
    $("#freedomChips").append(b);
  });

  // ---------------------------------------------------------------- Chapter 10: years slider
  const slider = $("#yearSlider");
  function counts(y) {
    const us = new Set(pieceKeys.map(k => unitAt(k, y)));
    let st = 0, ut = 0;
    for (const u of us) { if (G.units[u].c === "state") st++; else if (G.units[u].c === "ut") ut++; }
    return [st, ut];
  }
  function paintYear(y) {
    year = y;
    slider.value = y;
    $("#yearNow").textContent = y;
    const [st, ut] = counts(y);
    $("#nStates").textContent = st;
    $("#nUTs").textContent = ut;
    let m = G.milestones[0];
    for (const row of G.milestones) if (row[0] <= y) m = row;
    $("#yearCaption").textContent = `${m[0]}: ${T(m[1])}`;
    if (state !== "changes") return;
    $("#mapYear").textContent = y;
    paintPieces(y, "lang");
    langLegend(y);
    fitMap();
  }
  const MILE_YEARS = new Set(G.milestones.map(m => m[0]));
  function stopYears() { clearTimeout(timer); timer = null; $("#playYears").textContent = T("▶ Play"); }
  function stepYears() {
    if (year >= 2026) { stopYears(); return; }
    paintYear(year + 1);
    timer = setTimeout(stepYears, MILE_YEARS.has(year) ? 1500 : 160);
  }
  $("#playYears").onclick = () => {
    if (timer) { stopYears(); return; }
    if (state !== "changes") $("#cap10").scrollIntoView({ behavior: "smooth", block: "center" });
    if (year >= 2026) paintYear(1956);
    $("#playYears").textContent = T("⏸ Pause");
    timer = setTimeout(stepYears, 400);
  };
  slider.oninput = () => { stopYears(); paintYear(+slider.value); };
  paintYear(1956);

  // ---------------------------------------------------------------- Numbers in the text
  $("#pctPrince").textContent = `${G.stats.princely_pct_1909}%`;
  $("#meterPrince").style.setProperty("--w", `${G.stats.princely_pct_1909}%`);
  $("#nMughal").textContent = `${G.stats.mughal_pct}%`;

  // ---------------------------------------------------------------- Map as a list (for screen readers and for printing)
  function eraTable(key, target) {
    const rows = G.eras[key].units.slice().sort((a, b) => b.a - a.a)
      .map(u => `<tr><td>${esc(T(u.n))}</td><td>${esc(T(CAT_LABEL[u.c] || u.c))}</td><td>${esc(u.i ? T(u.i) : "")}</td></tr>`).join("");
    $(target).innerHTML = `<div class="table-wrap"><table class="data-table"><thead><tr><th>${T("Name")}</th><th>${T("Kind")}</th><th>${T("Note")}</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  }
  eraTable("-250", "#table-maurya");
  eraTable("1707", "#table-mughal");
  eraTable("1760", "#table-1760");
  eraTable("1909", "#table-1909");
  function yearTable(y, target) {
    const us = [...new Set(pieceKeys.map(k => unitAt(k, y)))].filter(u => ["state", "ut", "area"].includes(G.units[u].c))
      .sort((a, b) => T(G.units[a].n).localeCompare(T(G.units[b].n), document.documentElement.lang));
    const kind = { state: T("State"), ut: T("Union territory"), area: T("Special area") };
    $(target).innerHTML = `<div class="table-wrap"><table class="data-table"><thead><tr><th>${T("Name")}</th><th>${T("Kind")}</th><th>${T("Main languages")}</th></tr></thead><tbody>${us.map(u => `<tr><td>${esc(T(G.units[u].n))}</td><td>${kind[G.units[u].c]}</td><td>${esc(TL(G.units[u].lang))}</td></tr>`).join("")}</tbody></table></div>`;
  }
  yearTable(1956, "#table-1956");
  yearTable(2026, "#table-today");

  // ---------------------------------------------------------------- Chapters and scrolling
  const chapters = [...document.querySelectorAll(".chap")];
  function readingLine() {
    if (innerWidth >= 900) return innerHeight * 0.5;
    const mapBottom = $(".map-col").getBoundingClientRect().bottom;
    return mapBottom + (innerHeight - mapBottom) * 0.35;
  }
  function updateChapter() {
    const line = readingLine();
    let cur = chapters[0];
    for (const c of chapters) if (c.getBoundingClientRect().top < line) cur = c;
    chapters.forEach(c => c.classList.toggle("active", c === cur));
    setState(cur.dataset.map);
  }
  const bar = $("#progressBar");
  const onScroll = () => {
    const h = document.documentElement;
    bar.style.width = `${(h.scrollTop / Math.max(1, h.scrollHeight - h.clientHeight)) * 100}%`;
    updateChapter();
  };
  addEventListener("resize", () => { const s = state; state = null; setState(s); fitMap(); });
  addEventListener("scroll", onScroll, { passive: true });
  onScroll();

  // ---------------------------------------------------------------- Your place through time
  const ERA_ROWS = [[T("250 BCE"), "-250"], ["1707", "1707"], ["1760", "1760"], ["1909", "1909"], ["1947", 1947], ["1956", 1956], [T("Today"), 2026]];
  const sel = $("#placeSel");
  G.places.slice().sort((a, b) => T(a.n).localeCompare(T(b.n), document.documentElement.lang)).forEach(p => sel.append(html("option", { value: p.n }, `${T(p.n)} (${T(p.today)})`)));
  function showPlace(name) {
    const p = placeBy(name);
    const rows = ERA_ROWS.map(([lbl, key]) => {
      let text, color;
      if (typeof key === "string") {
        const u = G.eras[key].units.find(v => v.n === p.e[key]);
        text = p.e[key] ? T(p.e[key]) : "—";
        color = u ? (u.c === "kingdom" ? KINGDOM[1] : CAT[u.c]) : "#ccc";
        const extra = u ? T(CAT_LABEL[u.c]) : "";
        return `<tr><th scope="row">${lbl}</th><td style="--c:${color}">${esc(text)}${extra && !text.startsWith(extra) ? `<small>${esc(extra)}</small>` : ""}</td></tr>`;
      }
      const unit = unitAt(p.piece, key);
      const u = G.units[unit];
      const kind = { state: T("State of India"), ut: T("Union territory of India"), area: "", india: "", foreign: "", euro: T("European colony") }[u.c];
      color = u.c === "euro" ? CAT.euro : u.c === "foreign" ? CAT.foreign : key === 1947 ? CAT.india : "#f0c05a";
      return `<tr><th scope="row">${lbl}</th><td style="--c:${color}">${esc(T(u.n))}${kind ? `<small>${esc(kind)}</small>` : ""}</td></tr>`;
    });
    $("#placeTable tbody").innerHTML = rows.join("");
  }
  sel.onchange = () => showPlace(sel.value);
  sel.value = "Delhi";
  showPlace("Delhi");

  // ---------------------------------------------------------------- Name cards
  C.FLIPS.forEach(f => {
    const front = T("Before: {old}. Flip to see the new name.", f), back = T("Now: {now}, since {y}. {why}", f);
    const b = html("button", { type: "button", class: "flip", "aria-pressed": "false", "aria-label": front });
    b.innerHTML = `<span class="flip-in"><span class="face front"><span class="ico" aria-hidden="true">${f.ico}</span><small>${T("It used to be")}</small><b>${esc(f.old)}</b><span class="turn" aria-hidden="true">${T("↻ flip")}</span></span><span class="face back"><small>${T("Since {y}", f)}</small><b>${esc(f.now)}</b><span>${esc(f.why)}</span></span></span>`;
    b.onclick = () => {
      const on = b.getAttribute("aria-pressed") !== "true";
      b.setAttribute("aria-pressed", on);
      b.setAttribute("aria-label", on ? back : front);
    };
    $("#flips").append(b);
  });

  // ---------------------------------------------------------------- Quiz
  const quiz = $("#quiz");
  let score = 0, answered = 0;
  function buildQuiz() {
    quiz.replaceChildren(); score = 0; answered = 0; $("#quizEnd").hidden = true;
    C.QUIZ.forEach((item, qi) => {
      const fs = html("fieldset", { class: "qz" });
      fs.append(html("legend", {}, `${qi + 1}. ${item.q}`));
      const opts = html("div", { class: "qz-opts" }), fb = html("p", { class: "qz-fb", "aria-live": "polite" });
      item.a.forEach((txt, ai) => {
        const b = html("button", { type: "button" }, txt);
        b.onclick = () => {
          if (fs.classList.contains("done")) return;
          fs.classList.add("done");
          const right = ai === item.ok;
          if (right) score++;
          b.classList.add(right ? "ok" : "ko");
          opts.children[item.ok].classList.add("ok");
          fb.textContent = `${right ? T("✅ Well done!") : T("❌ Not quite.")} ${item.why}`;
          if (++answered === C.QUIZ.length) finish();
        };
        opts.append(b);
      });
      fs.append(opts, fb);
      quiz.append(fs);
    });
  }
  function finish() {
    const medal = score === C.QUIZ.length ? "🏆" : score >= 5 ? "🏅" : "🌱";
    $("#quizScore").innerHTML = `${medal} ${T("You got <b>{n} out of {total}</b>!", { n: score, total: C.QUIZ.length })}`;
    $("#quizEnd").hidden = false;
  }
  $("#quizAgain").onclick = buildQuiz;
  buildQuiz();

  window.__app = { setState, paintYear, proj };
})();
